const openAddUserSheet = qParams.sheet === "add";
const openLinkUserSheet = qParams.sheet === "link";

const { data: users, isFetching: isFetchingUsers } = useQuery({
  queryKey: [
    "organizationUsers",
    id,
    qParams.name,
    qParams.phone_number,
    qParams.page,
    isServiceAccount,
  ],
  queryFn: query.debounced(organizationApi.listUsers, {
    pathParams: { id },
    queryParams: {
      username: qParams.name,
      phone_number: qParams.phone_number,
      page: qParams.page,
      limit: resultsPerPage,
      offset: ((qParams.page || 1) - 1) * resultsPerPage,
      is_service_account: isServiceAccount,
    },
  }),
  enabled: !!id,
});

if (!id) {
  return null;
}

return (
  <>
    <OrganizationLayout
      id={id}
      navOrganizationId={navOrganizationId}
      setOrganization={setOrganization}
      routeContext={routeContext}
    >
      {({ orgPermissions }) => {
        const {
          canCreateUser,
          canManageOrganizationUsers,
          canCreateServiceAccount,
        } = getPermissions(hasPermission, orgPermissions);
        return (
          <div className="space-y-4">
            <Frame>
              <FrameHeader className="flex-row flex-wrap items-center justify-between gap-3">
                <SearchInput
                  options={searchOptions}
                  onSearch={handleSearch}
                  onFieldChange={handleFieldChange}
                  className="w-full sm:max-w-sm"
                />
                <div className="flex flex-wrap items-center gap-2">
                  <EntityBadge
                    title={
                      isServiceAccount ? t("service_accounts") : t("users")
                    }
                    count={users?.count}
                    isFetching={isFetchingUsers}
                  />
                  <div className="flex flex-wrap gap-2">
                    {(canCreateUser || canCreateServiceAccount) && (
                      <AddUserSheet
                        open={openAddUserSheet}
                        setOpen={(open) => {
                          updateQuery({ sheet: open ? "add" : "" });
                        }}
                        onUserCreated={(user, meta) => {
                          const skipLinkingCurrentOrganization =
                            organization?.org_type === "role" &&
                            !!meta?.roleOrgIds.includes(id);

                          updateQuery({
                            sheet: skipLinkingCurrentOrganization
                              ? ""
                              : "link",
                            username: skipLinkingCurrentOrganization
                              ? ""
                              : user.username,
                          });
                        }}
                        organizationId={id}
                        isServiceAccount={isServiceAccount}
                      />
                    )}
                    {canManageOrganizationUsers && (
                      <LinkUserSheet
                        organizationId={id}
                        open={openLinkUserSheet}
                        setOpen={(open) => {
                          updateQuery({
                            sheet: open ? "link" : "",
                            username: "",
                          });
                        }}
                        preSelectedUsername={qParams.username}
                        isServiceAccount={isServiceAccount}
                      />
                    )}
                  </div>
                </div>
              </FrameHeader>
              <FramePanel>
                {!isFetchingUsers && users?.results?.length === 0 ? (
                  <div className="p-2 text-center text-sm text-muted-foreground">
                    {t("no_users_found")}
                  </div>
                ) : (
                  <div className="grid grid-cols-1 gap-4 lg:grid-cols-2 xl:grid-cols-3">
                    {isFetchingUsers ? (
                      <CardGridSkeleton count={6} />
                    ) : (
                      users?.results?.map((userRole) => (
                        <UserCard
                          key={userRole.user.id}
                          user={userRole.user}
                          roleName={userRole.role.name}
                          editRoleAction={
                            canManageOrganizationUsers && (
                              <EditUserRoleSheet
                                organizationId={id}
                                userRole={userRole}
                                trigger={
                                  <Button
                                    variant="link"
                                    size="sm"
                                    className="underline text-gray-500"
                                  >
                                    <span>{t("edit")}</span>
                                  </Button>
                                }
                              />
                            )
                          }
                          isServiceAccount={isServiceAccount}
                        />
                      ))
                    )}
                  </div>
                )}
              </FramePanel>
            </Frame>
            <Pagination totalCount={users?.count || 0} />

