                 <SearchInput
                   options={[
                     {
                       key: "name",
                       type: "text",
                       placeholder: t("search_by_facility_name"),
                       value: qParams.name || "",
                       display: t("name"),
                     },
                   ]}
                   onSearch={(key, value) =>
                     updateQuery({
                       [key]: value || undefined,
                     })
                   }
                   showSearchIcon
                   className="w-full sm:max-w-sm"
                 />
                 <div className="flex flex-wrap items-center gap-2">
                   {canCreateFacility && (
                     <AddFacilitySheet organizationId={id} />
                   )}
                 </div>
               </FrameHeader>
               <FramePanel>
                 {!isFetching && facilities?.results?.length === 0 ? (
                   <div className="p-2 text-center text-sm text-muted-foreground">
                     {t("no_facilities_found")}
                   </div>
                 ) : (
                   <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                     {isFetching
                       ? Array.from({ length: 8 }, (_, index) => (
                           <OrganizationFacilityCardSkeleton key={index} />
                         ))
                       : facilities?.results?.map((facility) => (
                           <OrganizationFacilityCard
                             key={facility.id}
                             facility={facility}
                             showSettings={isGeoAdmin}
                           />
                         ))}
                   </div>
                 )}
               </FramePanel>
             </Frame>
             <Pagination totalCount={facilities?.count ?? 0} />
           </div>
         );
       }}
     </OrganizationLayout>
   );
 }

