git --no-pager diff --check; node --input-type=module <<'NODE'
import ts from 'typescript';
import fs from 'node:fs';
import assert from 'node:assert/strict';
for (const name of ['OrganizationView', 'OrganizationPatients', 'OrganizationFacilities', 'OrganizationUsers']) {
  const path = `src/pages/Organization/${name}.tsx`;
  const source = ts.createSourceFile(path, fs.readFileSync(path, 'utf8'), ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  let frameCount = 0;
  let badgeCount = 0;
  function visit(node, inFrame = false) {
    const jsx = ts.isJsxElement(node) || ts.isJsxSelfClosingElement(node);
    const tag = jsx ? (ts.isJsxElement(node) ? node.openingElement.tagName : node.tagName).getText(source) : '';
    if (tag === 'Frame') frameCount++;
    if (tag === 'EntityBadge') {
      badgeCount++;
      assert.ok(!inFrame, `${name}: heading must be outside Frame`);
    }
    if (['AddFacilitySheet', 'AddUserSheet', 'LinkUserSheet'].includes(tag)) {
      assert.ok(!inFrame, `${name}: actions must be outside Frame`);
    }
    if (tag === 'SearchInput') assert.ok(inFrame, `${name}: search must stay inside Frame`);
    ts.forEachChild(node, child => visit(child, inFrame || tag === 'Frame'));
  }
  visit(source);
  assert.equal(frameCount, 1);
  assert.equal(badgeCount, 1);
  console.log(`PASS ${name}: heading/actions outside Frame; search inside`);
}
NODE

