git --no-pager diff --check; node --input-type=module <<'NODE'
import fs from 'node:fs';
import ts from 'typescript';
import assert from 'node:assert/strict';
const file = 'src/pages/Organization/components/OrganizationLayout.tsx';
const text = fs.readFileSync(file, 'utf8');
const source = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
const elements = [];
function visit(node) {
  if (ts.isJsxElement(node)) elements.push(node);
  ts.forEachChild(node, visit);
}
visit(source);
const byTag = tag => elements.filter(node => node.openingElement.tagName.getText(source) === tag);
const titles = byTag('CareUIPageTitle');
const crumbs = byTag('Breadcrumb');
assert.equal(titles.length, 1);
assert.equal(crumbs.length, 1);
assert.ok(titles[0].pos < crumbs[0].pos, 'Title must precede breadcrumbs');
assert.ok(titles[0].getText(source).includes('{org.name}'));
assert.equal(byTag('h2').length, 0, 'Breadcrumb must not contain a duplicate heading');
assert.ok(text.includes('<BreadcrumbSeparator />'), 'Use chevron separators');
assert.ok(byTag('BreadcrumbPage')[0].getText(source).includes('font-semibold'));
console.log('PASS: organization title above breadcrumbs; current crumb emphasized; chevron separators retained.');
