node --input-type=module <<'NODE'
import fs from 'node:fs';
const path = 'public/locale/en.json';
const additions = {
  organization_children_description: 'View the organizations within this organization.',
  organization_patients_description: 'View patients associated with this organization.',
  organization_facilities_description: 'View facilities associated with this organization.',
  organization_users_description: 'View users associated with this organization.',
  organization_service_accounts_description: 'View service accounts associated with this organization.',
};
const fd = fs.openSync(path, 'r+');
try {
  const size = fs.fstatSync(fd).size;
  const tail = Buffer.alloc(Math.min(size, 64));
  fs.readSync(fd, tail, 0, tail.length, size - tail.length);
  const match = tail.toString().match(/\}(\s*)$/);
  if (!match) throw new Error('English locale does not end in a JSON object');
  const offset = size - Buffer.byteLength(match[0]);
  const lines = Object.entries(additions).map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)}`).join(',\n');
  const suffix = `,\n${lines}\n}\n`;
  fs.writeSync(fd, suffix, offset, 'utf8');
  fs.ftruncateSync(fd, offset + Buffer.byteLength(suffix));
} finally {
  fs.closeSync(fd);
}
